syntax:
class Base {
public:
    virtual void virtFunc();  // Declares a virtual function; compiler adds a vptr to the class layout and generates a vtable
};

class Derived : public Base {
public:
    void virtFunc() override;  // Overrides the virtual function; compiler updates the vtable for Derived to point to this implementation
};

code_example:
#include <iostream>

class Base {
public:
    virtual void virtFunc() {
        std::cout << "Base's virtual function" << std::endl;
    }
};

class Derived : public Base {
public:
    void virtFunc() override {
        std::cout << "Derived's virtual function" << std::endl;
    }
};

int main() {
    Base* ptr = new Derived();  // Pointer to Base, but points to Derived object
    ptr->virtFunc();  // Runtime dispatch via vtable
    delete ptr;
    return 0;
}
